-- PYTH BOMB: perguntas GERAIS em alternativas para o "Classic A/B/C/D" (parte 1 de 3) — 200 perguntas
-- Rode DEPOIS do 043_classic_abcd.sql. Pode rodar de novo sem duplicar. Elas entram DESLIGADAS do Classic de digitar (active = false) e do Recap (recap_on = false).
alter table public.questions add column if not exists classic_on boolean not null default false;
alter table public.questions add column if not exists classic_tier int not null default 0;
-- A mesma pergunta pode existir em dois formatos (digitar e alternativas) com o MESMO texto. O índice antigo olhava só o texto
-- e barrava isso (erro 23505 questions_text_unique); o novo olha texto + tipo. Seguro de rodar de novo.
create unique index if not exists questions_text_kind_unique on public.questions (lower(text), kind);
drop index if exists public.questions_text_unique;
insert into public.questions (text, accepted_answers, category, difficulty, source_reference, verified, active, kind, wrong_options, recap_on, classic_on, classic_tier)
select v.text, v.accepted_answers, v.category, v.difficulty, v.source_reference, v.verified, v.active, v.kind, v.wrong_options, v.recap_on, v.classic_on, v.classic_tier
